('Біла емаль','OUTSIDE','https://korfad.com.ua/content/images/7/278x600l80mc0/dverne-polotno-calypso-800-kh-2000-bila-emal-14328446142517.webp',1),('Біла емаль','INSIDE','https://korfad.com.ua/content/images/12/278x600l80mc0/dverne-polotno-calypso-800-kh-2010-bila-emal-inside-20649741716557.webp',2),('RAL 1013 Шампань','OUTSIDE','https://korfad.com.ua/content/images/17/278x600l80mc0/40256734871857.webp',3),('RAL 1013 Шампань','INSIDE','https://korfad.com.ua/content/images/22/278x600l80mc0/30102493119525.webp',4),('RAL 7036 Сірий','OUTSIDE','https://korfad.com.ua/content/images/48/278x600l80mc0/94447794795370.webp',5),('RAL 7036 Сірий','INSIDE','https://korfad.com.ua/content/images/3/278x600l80mc0/34968280331789.webp',6),('RAL 7047 Світло Сірий','OUTSIDE','https://korfad.com.ua/content/images/6/278x600l80mc0/51524794009788.webp',7),('RAL 7047 Світло Сірий','INSIDE','https://korfad.com.ua/content/images/11/278x600l80mc0/58234534447123.webp',8),('Тауп','OUTSIDE','https://korfad.com.ua/content/images/8/278x600l80mc0/12678472348347.webp',9),('Тауп','INSIDE','https://korfad.com.ua/content/images/13/278x600l80mc0/78594643540621.webp',10);
insert into public.products(slug,category,brand,collection,name,material,style,color,price,description,features,image_path,sort_order,is_available) select 'korfad-ex-calypso','interior','KORFAD','EXELLENCE','KORFAD CALYPSO','Фарбоване покриття','Сучасний','Заводські кольори RAL','Ціна за запитом','KORFAD CALYPSO — фарбовані міжкімнатні двері колекції EXELLENCE. Підтверджені кольори RAL та виконання OUTSIDE / INSIDE.',jsonb_build_array('Фабрика KORFAD','Колекція EXELLENCE'),min(i),99999,false from k on conflict(slug) do update set image_path=excluded.image_path,description=excluded.description;
insert into public.product_options(product_slug,option_group,group_label,label,sort_order) select 'korfad-ex-calypso','color','Колір',c,min(n) from k group by c on conflict(product_slug,option_group,label) do update set sort_order=excluded.sort_order,is_active=true;
insert into public.product_options(product_slug,option_group,group_label,label,sort_order) values('korfad-ex-calypso','configuration','Відкривання','OUTSIDE',10),('korfad-ex-calypso','configuration','Відкривання','INSIDE',20) on conflict(product_slug,option_group,label) do update set is_active=true;
insert into public.product_variants(product_slug,selections,image_path,sort_order,is_active) select 'korfad-ex-calypso',jsonb_build_object('color',c,'configuration',o),i,n,true from k on conflict(product_slug,selections) do update set image_path=excluded.image_path,is_active=true;
